/// Look up the glyph bitmap for `ch`, if it's in the supported ASCII
/// printable range (0x20..=0x7E). Anything else returns `None`.
pub fn glyph(ch: char) -> Option<&'static [u8; CELL_H]> {
    let code = ch as u32;
    if (0x20..=0x7E).contains(&code) {
        Some(&FONT_6X13[(code - 0x20) as usize])
    } else {
        None
    }
}
